#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <string.h>

#define FILENAME "test_file.dat"
#define INITIAL_SIZE 20
#define TRUNCATED_SIZE 8

int main() {
    int fd;
    char buffer[INITIAL_SIZE] = "0123456789ABCDEFGHIJ";

    // 1. Create and write initial data (20 bytes)
    if ((fd = open(FILENAME, O_CREAT | O_RDWR | O_TRUNC, 0644)) == -1) {
        perror("open");
        return EXIT_FAILURE;
    }
    if (write(fd, buffer, INITIAL_SIZE) != INITIAL_SIZE) {
        perror("write");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Initial file size: %ld bytes.\n", (long)lseek(fd, 0, SEEK_END));

    // 2. Use ftruncate() to shorten the file
    if (ftruncate(fd, TRUNCATED_SIZE) == -1) {
        perror("ftruncate");
        close(fd);
        return EXIT_FAILURE;
    }
    printf("File truncated using ftruncate() to %d bytes.\n", TRUNCATED_SIZE);

    // Verify new size
    long new_size = lseek(fd, 0, SEEK_END);
    printf("Actual new size: %ld bytes.\n", new_size);

    close(fd);

    // 3. Demonstrate extension using truncate() (by path)
    // Extend the 8-byte file to 40 bytes. The new space will be null bytes.
    off_t extended_length = 40;
    if (truncate(FILENAME, extended_length) == -1) {
        perror("truncate");
        return EXIT_FAILURE;
    }
    printf("File extended using truncate() to %ld bytes.\n", (long)extended_length);

    unlink(FILENAME); // Clean up
    return EXIT_SUCCESS;
}
